function N(f){return f.slice().sort((o,n)=>o-n)}function q(f){const o=N(f.map(Math.abs)).filter(t=>t>1e-8),n=[];for(let t=1;t<o.length;t++)n.push(o[t]-o[t-1]);const e=[];for(let t=0;t+1<n.length;t++){const r=Math.min(n[t],n[t+1]),s=Math.max(n[t],n[t+1]);e.push(r/s)}return e}const k=(()=>{const o=[],n=[0];for(let t=0;t<200001;t++)o.push(t/2e5);let e=0;for(let t=1;t<200001;t++){const r=s=>3.375*Math.pow(s+s*s,2)/Math.pow(1+s+s*s,5);e+=(r(o[t])+r(o[t-1]))/2*(o[t]-o[t-1]),n.push(e)}return{grid:o,cdf:n.map(t=>t/e)}})();function w(f){if(f<=0)return 0;if(f>=1)return 1;let o=0,n=k.grid.length-1;for(;n-o>1;){const t=o+n>>1;k.grid[t]<=f?o=t:n=t}const e=(f-k.grid[o])/(k.grid[n]-k.grid[o]);return k.cdf[o]*(1-e)+k.cdf[n]*e}function S(f,o){const n=Math.sqrt(o),e=(n+.12+.11/n)*f,t=Math.floor(Math.sqrt(2)/e)+1;let r=0;for(let s=1;s<=t;s++)r+=Math.pow(-1,s-1)*Math.exp(-2*s*s*e*e);return Math.max(0,Math.min(1,2*r))}function E(f){const o=N(f),n=o.length;let e=0,t=0;for(let s=0;s<n;s++){const c=w(o[s]);e=Math.max(e,(s+1)/n-c),t=Math.max(t,c-s/n)}const r=Math.max(e,t);return{D:r,p:S(r,n)}}function O(f,o){const n=[];for(const e of o){let t=0;for(let r=0;r<e;r++){const s=r>0?f[r-1]:f[r],c=r+1<e?f[r+1]:f[r],p=(s+c)/2;t+=Math.abs(f[r]-p)}n.push({N:e,b:t/e})}return n}function _(f,o,n){const e=N(f),t=[];for(const r of o){let s=0,c=0;const p=Math.max(1,Math.floor(e.length/n));for(let u=0;u+r<e.length;u+=p){const h=e[u];let i=0;for(let l=u;l<e.length&&e[l]<h+r;l++)i++;if(s+=Math.pow(i-r,2),c++,c>=n)break}t.push({L:r,sigma2:s/Math.max(c,1)})}return t}function L(f,o){const n=N(f),e=[];for(const t of o){const s=Math.max(1,Math.floor(n.length/300));let c=0,p=0;for(let u=0;u+t<n.length;u+=s){const h=[];for(let M=u;M<n.length&&h.length<=t+1;M++)h.push(M-u);const i=h.length;if(i<4)continue;let l=0,m=0,a=0,g=0;for(let M=0;M<i;M++){const b=n[u+M];l+=b,m+=h[M],a+=b*b,g+=b*h[M]}const d=i*a-l*l;if(d<=0)continue;const x=(i*g-l*m)/d,y=(m-x*l)/i;let R=0;for(let M=0;M<i;M++){const b=y+x*n[u+M];R+=Math.pow(h[M]-b,2)}if(c+=R/t,p++,p>=300)break}e.push({L:t,delta3:c/Math.max(p,1)})}return e}function v(f){const o=f.length,n=f.map(t=>t.slice());for(let t=0;t<200;t++){let r=0;for(let s=0;s<o;s++)for(let c=s+1;c<o;c++)r+=n[s][c]*n[s][c];if(r<1e-24)break;for(let s=0;s<o;s++)for(let c=s+1;c<o;c++){if(Math.abs(n[s][c])<1e-15)continue;const p=(n[c][c]-n[s][s])/(2*n[s][c]),u=(p>=0?1:-1)/(Math.abs(p)+Math.sqrt(1+p*p)),h=1/Math.sqrt(1+u*u),i=u*h;for(let l=0;l<o;l++){const m=n[l][s],a=n[l][c];n[l][s]=h*m-i*a,n[l][c]=i*m+h*a}for(let l=0;l<o;l++){const m=n[s][l],a=n[c][l];n[s][l]=h*m-i*a,n[c][l]=i*m+h*a}}}const e=[];for(let t=0;t<o;t++)e.push(n[t][t]);return N(e)}self.onmessage=f=>{const{type:o,payload:n}=f.data;try{if(o==="stats"){const{zeros:e}=n,r=O(e,[100,500,1e3,2e3,5e3,1e4,2e4,5e4]),s=q(e),c=E(s),p=s.reduce((l,m)=>l+m,0)/s.length,h=_(e,[2,5,10,20,50,100,200,500,1e3],500),i=L(e,[2,5,10,20,50,100,200]);self.postMessage({type:"stats",ok:!0,result:{bN:r,rMean:p,ks:c,nRatios:s.length,sig2:h,d3:i,refs:{R_GUE:.59965,R_GOE:.5359,R_POISSON:.38629}}})}else if(o==="spinor"){const{classes:e,edges:t,representative:r}=n,s=56,c=[];for(const a of e){if(a.orbit!==0)continue;const g=[];for(let x=0;x<s;x++)g.push(new Array(s).fill(0));t.forEach(([x,y],R)=>{g[x][y]=a.signs[R],g[y][x]=a.signs[R]});const d=v(g);a.cls===r?c.unshift(d):c.push(d)}const p=c[0];let u=0;for(let a=0;a<c.length;a++)for(let g=a+1;g<c.length;g++)for(let d=0;d<s;d++)u=Math.max(u,Math.abs(c[a][d]-c[g][d]));const h=N(p.map(Math.abs)),i=[];for(let a=0;a+1<h.length;a++){const g=h[a+1]-h[a];g>1e-8&&i.push(g)}const l=[];for(let a=0;a+1<i.length;a++)l.push(Math.min(i[a],i[a+1])/Math.max(i[a],i[a+1]));const m=l.reduce((a,g)=>a+g,0)/l.length;self.postMessage({type:"spinor",ok:!0,result:{nSpectra:c.length,isomax:u,rMean:m,spectrum:p,nZero:h.filter(a=>a<1e-8).length}})}}catch(e){self.postMessage({type:o,ok:!1,error:String(e)})}};
